-- IMPORTAÇÃO CONFERIDA: Base Completa, CF M02, revisão guiada, capítulos 01 a 13.
-- Verifique a versão 4; se ela tiver mudado, interrompa e faça merge em vez de sobrescrever.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('basecompleta-reader-19fwys4-cf-m02'));
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM central_content_overrides WHERE content_id='reader:19fwys4' AND revision=4 AND position('<figure' in html)=0) THEN
 RAISE EXCEPTION 'Módulo não está na revisão 4 sem imagens; nenhuma mudança foi feita';
 END IF;
END $$;
